import{_ as a,o as s,c as e,a5 as t}from"./chunks/framework.BwlBv862.js";const c=JSON.parse('{"title":"プラグインの梱包・署名・レジストリ","description":"","frontmatter":{"title":"プラグインの梱包・署名・レジストリ","docId":"developer.plugins.packaging-registry","translationKey":"developer.plugins.packaging-registry","locale":"ja","audience":"developer","featureStatus":"available","contentStatus":"reviewed","sourceLocale":"en","sourceRevision":"b5c1b8dc63aafc5216467a00317c6670ac6744235abfc724fe372f3a28427ee8","translationRevision":"91610226f73b8a2c806aca378c3ce8d66c9c93865098821f855da399091cfa4d","order":280},"headers":[],"relativePath":"ja/developer/plugins/packaging-registry.md","filePath":"ja/developer/plugins/packaging-registry.md","lastUpdated":1794611623000}'),n={name:"ja/developer/plugins/packaging-registry.md"};function l(p,i,r,h,o,d){return s(),e("div",null,[...i[0]||(i[0]=[t(`<h1 id="plugin-packaging-signing-and-registries" tabindex="-1">プラグインの梱包・署名・レジストリ <a class="header-anchor" href="#plugin-packaging-signing-and-registries" aria-label="Permalink to &quot;プラグインの梱包・署名・レジストリ {#plugin-packaging-signing-and-registries}&quot;">​</a></h1><h2 id="goal-and-prerequisites" tabindex="-1">目的と前提条件 <a class="header-anchor" href="#goal-and-prerequisites" aria-label="Permalink to &quot;目的と前提条件 {#goal-and-prerequisites}&quot;">​</a></h2><p>バイト列、発行者権限、ホスト互換性を別々に確認できるパッケージを配布します。検証済みプラグインと対応対象から始めます。署名の秘密鍵はリポジトリ外に保管し、レジストリルートの委任は運用者が別途担当します。</p><h2 id="prepare-a-reviewable-archive" tabindex="-1">確認可能なアーカイブを準備する <a class="header-anchor" href="#prepare-a-reviewable-archive" aria-label="Permalink to &quot;確認可能なアーカイブを準備する {#prepare-a-reviewable-archive}&quot;">​</a></h2><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">tiktools-plugin</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> validate</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --publish</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">tiktools-plugin</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> build</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --release</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">tiktools-plugin</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> keygen</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --id</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> acme-1</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --publisher</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> acme</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --out</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /private/path/keys</span></span></code></pre></div><p><code>build</code> はコンパイルして <code>.plugin</code> アーカイブを作ります。マニフェストの入口、アセット、ロケール、UI 出力、必要なランタイム依存を <code>checksums.json</code> とともに含めます。native/process は対象に合う成果物が必要です。JavaScript のみなら可搬性を持ちますが、ネイティブアドオンや環境機能を使うと制約が加わります。</p><p>既存のビルド済みアーカイブでは、未確認のワイルドカードではなく正確なパスを使います。</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">tiktools-plugin</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> sign</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> dist-plugin/acme.hello-0.1.0.plugin</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --key</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /private/path/keys/acme-1.key.json</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">tiktools-plugin</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> verify</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> dist-plugin/acme.hello-0.1.0.plugin</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --trust</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /private/path/keys/acme-1.pub.json</span></span></code></pre></div><p>アーカイブ名を実際の対象別出力に置き換えます。署名はチェックサムを保護し、チェックサムは各ファイルを保護します。公開鍵は共有できますが、秘密鍵をソース管理やログに含めてはいけません。</p><h2 id="trust-and-update-policy" tabindex="-1">信頼と更新方針 <a class="header-anchor" href="#trust-and-update-policy" aria-label="Permalink to &quot;信頼と更新方針 {#trust-and-update-policy}&quot;">​</a></h2><p>静的レジストリはルート署名の権限と、委任された索引・発行者鍵を持ちます。発行者の名前空間承認とパッケージ完全性は別で、Cloud カタログのダイジェストはどちらの署名連鎖の代わりにもなりません。解決器はチャンネル、エンジン、スキーマ・プロトコル・ABI、ランタイム、対象を検査します。取り下げ、取り消し、非互換の版はファイルハッシュが一致しても対象外です。</p><p>インストール時は先に確認を表示します。自動更新には許可された方針、固定されていないパッケージ、互換の署名済み発行者、新権限がないことが必要です。権限拡大は確認が必要です。製品の Cloud カタログからのインストールと低水準の静的レジストリ作成は別で、通常の製品フローは任意のリモート URL を拒否します。</p><h2 id="expected-result-recovery-and-verification" tabindex="-1">期待される結果・復旧・検証 <a class="header-anchor" href="#expected-result-recovery-and-verification" aria-label="Permalink to &quot;期待される結果・復旧・検証 {#expected-result-recovery-and-verification}&quot;">​</a></h2><p>インストーラーは確認済みパッケージの適用前にバイト列を検証し、ロールバック・復旧状態を保持できます。開発用の配置は管理対象外です。信頼エラーでは未署名許可フラグを通常方針にせず、委任や発行者情報を修復します。起動が不確実なら置換を止め、保持した結果を照合します。</p><p>オフラインの検証には <code>bun scripts/task.ts rust test -p tiktools-plugin-package --locked</code> とレジストリテストを使います。技術形式の正本は<a href="https://github.com/nglmercer/TikTools-app/tree/remake/crates/tiktools-plugin-package/src" target="_blank" rel="noreferrer">パッケージ検証器</a> と<a href="https://github.com/nglmercer/TikTools-app/blob/remake/crates/tiktools-plugin-registry/src/model.rs" target="_blank" rel="noreferrer">レジストリモデル</a> です。公開基盤は運用者による別の受け入れ確認が必要です。</p><h2 id="operational-details" tabindex="-1">運用の詳細 <a class="header-anchor" href="#operational-details" aria-label="Permalink to &quot;運用の詳細 {#operational-details}&quot;">​</a></h2><p>終了コードだけでなく検証 JSON を判定します。<code>verify</code> は <code>signature.status</code> が <code>unsigned</code>・<code>untrusted</code> でも成功終了します。<code>verified</code> でパッケージ ID・発行者・key ID が期待どおりの場合だけ受け入れ、配布方針も確認します。ローカル <code>--trust</code> はその鍵との署名関係を示すだけで、レジストリ委任・名前空間承認ではありません。checksum だけでは発行権限・updater 信頼を証明できません。以下の自動判定は想定外を拒否します。</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">tiktools-plugin</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> verify</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> dist-plugin/acme.hello-0.1.0.plugin</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --trust</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /private/path/keys/acme-1.pub.json</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> &gt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> verification.json</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">bun</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -e</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;const r = await Bun.file(&quot;verification.json&quot;).json(); if (r.signature?.status !== &quot;verified&quot; || r.id !== &quot;acme.hello&quot; || r.signature.publisher !== &quot;acme&quot; || r.signature.keyId !== &quot;acme-1&quot;) throw new Error(&quot;Package trust did not match policy&quot;);&#39;</span></span></code></pre></div>`,18)])])}const g=a(n,[["render",l]]);export{c as __pageData,g as default};
